const flowCardProfiles = {};
const flowReplyCards = {};
const createExtendedHelpFlow = (spec) => {
  const materials = spec.materials.map((material) => ({
    ...material,
    id: `${spec.id}-${material.id}`,
    author: material.author,
    source: material.source,
    engagement: "共读回访 · 可展开全文",
    validUses: [material.tag],
    body: [material.opening, material.detail, material.turn, material.boundary]
  }));
  const profiles = {};
  const replies = {};
  materials.forEach((material, index) => {
    const source = spec.materials[index];
    const role = flowRoleProfiles[source.role] || flowRoleProfiles.fact;
    profiles[material.id] = { ...role, face: source.face, sourceFace: source.sourceFace, note: source.note };
    replies[material.id] = { quote: source.quote, source: source.sourceReply };
  });
  chapterDefinitions[spec.id] = {
    ...spec,
    id: spec.id,
    materials,
    tagOptions: [
      { id: "fact", label: "可核对事实" }, { id: "experience", label: "个人经历" },
      { id: "context", label: "当事人补充" }, { id: "risk", label: "需要留意的风险" }
    ],
    relationship: "熟人回访"
  };
  flowCardProfiles[spec.id] = profiles;
  flowReplyCards[spec.id] = replies;
};

extendedHelpFlowSpecs.forEach(createExtendedHelpFlow);
