function getMaterialClipScenes(material) {
  return materialClipScenes[state.chapterId]?.[material?.id] || material?.body?.map((text, index) => ({
    label: `现场记录 ${String(index + 1).padStart(2, "0")}`,
    time: `00:${String(index * 8).padStart(2, "0")}—00:${String(index * 8 + 7).padStart(2, "0")}`,
    text
  })) || [];
}

function getMaterialArticleParagraphs(material) {
  const paragraphs = Array.isArray(material?.body) && material.body.length
    ? material.body
    : getMaterialClipScenes(material).map((scene) => scene.text);
  return paragraphs.filter((paragraph) => String(paragraph || "").trim());
}

function getMaterialFeedMetrics(material) {
  return material.metrics || materialFeedMetrics[material.id] || { votes: "—", comments: "—", saves: "—", likes: "—" };
}

function getAvatarClass(key = "yuyi") {
  return key === "lotus-elder" ? "avatar-lotus-elder" : `avatar-sprite avatar-${key}`;
}

function getMaterialAvatarClass(material) {
  const avatarByMaterial = {
    official: "medical",
    oldGuide: "mature",
    experience: "young-experience",
    context: "yuyi",
    avoid: "fact-checker",
    softAd: "promo"
  };
  return getAvatarClass(material.avatarKey || avatarByMaterial[material.id] || "yuyi");
}

